.ds-primary-nav { background:var(--ground); color:var(--paper); font-family: var(--sans); font-size: 1.0625rem; line-height: 1.6; } .ds-primary-nav a { color:inherit; text-underline-offset:.3em; text-decoration-thickness:1px; } .ds-primary-nav { display: flex; gap: 32px; font-size: 17px; }
.ds-primary-nav a { text-decoration: none; }
.ds-primary-nav a[aria-current="true"] { color: var(--amber); text-decoration: underline; } :focus-visible { outline: 2px solid var(--amber); outline-offset: 5px; } @media(max-width:760px) { .ds-primary-nav { flex-wrap:wrap; gap:10px 20px; font-size:15px; } }

.ds-case-index { background:var(--ground); } .ds-case-index { display: flex; flex: 1; padding-top: 14px; min-width: 0; }
.ds-case-index a { flex: 1; min-width: 0; position: relative; text-align: center; padding: 34px 6px 0; text-decoration: none; font: 400 16px/1.5 var(--mono); color: var(--muted); }
.ds-case-index a::before { content: ""; width: 13px; height: 13px; border: 1px solid var(--paper); background: var(--ground); border-radius: 50%; position: absolute; top: 4px; left: calc(50% - 6.5px); z-index: 1; }
.ds-case-index a:not(:last-child)::after { content: ""; height: 1px; background: var(--muted); width: 100%; position: absolute; top: 10px; left: 50%; }
.ds-case-index a[aria-current="true"] { color: var(--amber); }
.ds-case-index a[aria-current="true"]::before { border-color: var(--amber); background: var(--amber); }
.ds-case-position { display: block; } :focus-visible { outline: 2px solid var(--amber); outline-offset: 5px; } @media(max-width:760px) { .ds-case-index { padding-top:0; } .ds-case-index a { font:400 12px/1.4 var(--sans); padding:26px 3px 0; overflow-wrap:anywhere; } .ds-case-position { font-family:var(--mono); font-size:11px; } }

.ds-case-card { font:400 1.0625rem/1.6 var(--sans); }
.ds-case-card :where(h2, p) { margin:0; }
.ds-case-card { flex: 0 0 var(--card-width); min-width: 0; min-height: var(--card-height); padding: 44px 60px 38px; border-radius: 3px; color: var(--ink); background: var(--paper); scroll-snap-align: center; display: flex; flex-direction: column; color-scheme: light; }
.ds-case-card h2 { font: 700 68px/1.04 var(--display); letter-spacing: -.035em; max-width: 12ch; margin-bottom: 28px; text-wrap: initial; }
.ds-case-summary { font-size: 28px; line-height: 1.45; max-width: 51ch; }
.ds-read-case { display: flex; align-items: center; gap: 16px; border-top: 1px solid var(--paper-line); padding-top: 16px; margin-top: 24px; font: 400 18px/1.5 var(--mono); text-decoration: none; }
.ds-read-case:hover { color: #81500a; }
.ds-arrow { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 1.6; vertical-align: middle; flex: none; }
.ds-case-card :focus-visible { outline:2px solid #86540c; outline-offset:5px; }
@media (min-width:1201px) and (max-width:1535px) { .ds-case-card { padding-inline:3.9063vw; } .ds-read-case { margin-top:1.5625vw; padding-top:1.0417vw; font-size:1.1719vw; } }
@media (max-width:1200px) { .ds-case-card { padding-inline:44px; } }
@media (max-width:760px) { .ds-case-card { min-height:540px; padding:28px 24px; } .ds-case-card h2 { line-height:1.1; max-width:15ch; } .ds-case-summary { overflow-wrap:break-word; } .ds-read-case { font-size:15px; gap:12px; } }
.ds-case-card:not(.ds-intro-card) { padding-block: 32px 26px; }
.ds-case-label { font: 500 13px/1.4 var(--sans); letter-spacing: .1em; text-transform: uppercase; color: #86540c; margin-bottom: 10px; }
.ds-case-card:not(.ds-intro-card) h2 { font-size: clamp(42px, 3.65vw, 56px); margin-bottom: 18px; }
.ds-case-card:not(.ds-intro-card) .ds-case-summary { font-size: clamp(19px, 1.43vw, 22px); line-height: 1.45; max-width: 32em; }
.ds-case-comparison { display: grid; grid-template-columns: 1fr .8fr 1fr; gap: 22px; margin: 28px 0 16px; }
.ds-case-comparison > div { min-width: 0; padding: 18px 20px; }
.ds-comparison-before { background: #eeeadf; }
.ds-comparison-after { background: #f7edd7; }
.ds-case-comparison dt, .ds-case-scope span { font: 600 12px/1.5 var(--sans); letter-spacing: .06em; text-transform: uppercase; color: #625540; }
.ds-case-comparison dd { margin: 10px 0 0; font-size: 17px; line-height: 1.45; }
.ds-case-comparison strong { display: block; font: 600 21px/1.2 var(--sans); letter-spacing: -.02em; margin-bottom: 12px; }
.ds-case-comparison .ds-comparison-decision { padding-inline: 0; text-align: center; align-self: center; }
.ds-comparison-decision dt { color: #86540c; }
.ds-comparison-decision dd { font-size: 18px; }
.ds-comparison-decision::after { content: ""; display: block; width: 80px; height: 3px; margin: 22px auto 0; background: var(--amber); }
.ds-case-scope { font-size: 16px; line-height: 1.45; margin-bottom: 20px; }
.ds-case-scope span { display: block; margin-bottom: 3px; }
.ds-case-card:not(.ds-intro-card) .ds-read-case { margin-top: auto; }
@media (min-width: 1536px) {
  .ds-case-card:not(.ds-intro-card) { min-height: 65.7svh; padding-top: 36px; }
  .ds-case-card:not(.ds-intro-card) h2 { font-size: 64px; }
  .ds-case-card:not(.ds-intro-card) .ds-case-summary { font-size: 25px; }
  .ds-case-comparison dd { font-size: 19px; }
  .ds-case-comparison strong { font-size: 23px; }
  .ds-case-scope { font-size: 18px; }
}
@media (min-width: 761px) and (max-width: 1535px) {
  .ds-case-comparison { gap: 18px; margin-top: 24px; }
  .ds-case-comparison > div { padding: 15px 16px; }
  .ds-case-comparison dd { font-size: 16px; }
  .ds-case-comparison strong { font-size: 19px; margin-bottom: 10px; }
  .ds-comparison-decision dd { font-size: 17px; }
}
@media (min-width: 761px) and (max-width: 1000px) {
  .ds-case-comparison { grid-template-columns: 1fr 1fr; gap: 16px; }
  .ds-case-comparison .ds-comparison-decision { grid-column: 1 / -1; grid-row: 2; text-align: left; }
  .ds-comparison-decision::after { margin-inline: 0; margin-top: 14px; }
}
@media (max-width: 760px) {
  .ds-case-card:not(.ds-intro-card) { padding: 28px 24px; }
  .ds-case-card:not(.ds-intro-card) h2 { font-size: clamp(2rem, 8vw, 3rem); margin-bottom: 18px; }
  .ds-case-card:not(.ds-intro-card) .ds-case-summary { font-size: 18px; }
  .ds-case-label { font-size: 12px; }
  .ds-case-comparison { grid-template-columns: 1fr; gap: 16px; margin-top: 24px; }
  .ds-case-comparison > div { padding: 18px; }
  .ds-case-comparison strong { font-size: 21px; }
  .ds-case-comparison .ds-comparison-decision { padding: 4px 18px; text-align: left; }
  .ds-comparison-decision dd { font-size: 17px; }
  .ds-comparison-decision::after { width: 56px; margin: 16px 0 0; }
  .ds-case-scope { font-size: 16px; margin-bottom: 22px; }
}

